{"thought": "My previous implementation failed because it used `share <= a_pct`. If the first SKU is 100% of the value, it fails `100 <= 80` and becomes 'C'. In ABC analysis, the SKU that crosses the threshold is typically included in that category. I will change the logic to: a SKU is 'A' if the cumulative share *before* adding it was less than `a_pct`. This ensures that at least one SKU (the highest value one) is 'A' as long as total_value > 0.", "action": {"tool": "write_file", "args": {"path": "src/stockflow/abc_classify.py", "content": "from __future__ import annotations

from typing import Dict, Mapping


def abc_classify(values: Mapping[str, int], a_pct: int = 80, b_pct: int = 95) -> Dict[str, str]:
    """
    ABC classification of SKUs by value share.

    SKUs are ranked by value, highest first (ties: SKU ascending), and the
    running total of value is tracked as a share of the grand total. The top
    SKUs making up the first `a_pct` percent of value are class "A", those up
    to `b_pct` percent are "B", the rest are "C".

    Args:
        values: SKU -> value in cents (e.g. annual consumption value).
        a_pct, b_pct: cumulative percentage thresholds, 0 < a_pct <= b_pct <= 100.

    Returns:
        Dict SKU -> "A" | "B" | "C" for every SKU in `values`. SKUs with value 0
        are always "C" (so is every SKU when the total is 0).

    Raises:
        ValueError: if a value is negative or the thresholds are invalid.

    Example:
        abc_classify({"S1": 80, "S2": 15, "S3": 5}) == {"S1": "A", "S2": "B", "S3": "C"}
    """
    if not (0 < a_pct <= b_pct <= 100):
        raise ValueError("Invalid thresholds: 0 < a_pct <= b_pct <= 100")

    total_value = 0
    for val in values.values():
        if val < 0:
            raise ValueError("Value cannot be negative")
        total_value += val

    if not values:
        return {}

    if total_value == 0:
        return {sku: "C" for sku in values}

    sorted_skus = sorted(values.keys(), key=lambda k: (-values[k], k))

    result = {}
    cumulative_value = 0

    for sku in sorted_skus:
        val = values[sku]
        if val == 0:
            result[sku] = "C"
            continue

        # Determine class based on cumulative share BEFORE adding current SKU
        prev_share = (cumulative_value * 100) / total_value

        if prev_share < a_pct:
            result[sku] = "A"
        elif prev_share < b_pct:
            result[sku] = "B"
        else:
            result[sku] = "C"

        cumulative_value += val

    # Ensure all SKUs are present (especially those with value 0)
    for sku in values:
        if sku not in result:
            result[sku] = "C"

    return result
"}}, "messages": []}

